const paths={lock:'<rect x="5" y="10" width="14" height="11" rx="2"/><path d="M8 10V7a4 4 0 0 1 8 0v3m-4 5v2"/>',shield:'<path d="m12 3 8 3v6c0 4-4 7-8 9-4-2-8-5-8-9V6z"/><path d="m8 12 3 3 5-6"/>',doc:'<path d="M14 3H6v18h12V7zM14 3v5h4M9 12h6m-6 4h6"/>',card:'<rect x="3" y="5" width="18" height="14" rx="2"/><path d="M3 10h18M7 15h4"/>',users:'<circle cx="9" cy="7" r="3"/><path d="M3 21v-4a6 6 0 0 1 12 0v4M16 4a3 3 0 0 1 0 6m2 4c2 0 3 2 3 4v3"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',arrow:'<path d="M4 12h15m-6-6 6 6-6 6"/>',grid:'<rect x="3" y="3" width="7" height="7" rx="1"/><rect x="14" y="3" width="7" height="7" rx="1"/><rect x="3" y="14" width="7" height="7" rx="1"/><rect x="14" y="14" width="7" height="7" rx="1"/>',check:'<path d="m5 12 4 4 10-10"/>',flow:'<rect x="8" y="2" width="8" height="5" rx="1"/><path d="M12 7v5M5 16v-4h14v4"/><rect x="2" y="16" width="6" height="6" rx="1"/><rect x="16" y="16" width="6" height="6" rx="1"/>'};
const icon=n=>`<svg viewBox="0 0 24 24" aria-hidden="true">${paths[n]||paths.lock}</svg>`;
const navs=[['registration','shield','Complete registration'],['parentprofile','users','Parent profile'],['playerprofile','shield','Player profile'],['integrations','arrow','Send verification'],['tools','grid','Tool selectors'],['overview','grid','Vault overview'],['verification','shield','Verification'],['health','doc','Health documents'],['payments','card','Payments'],['access','users','Access & requests'],['activity','clock','Activity'],['workflow','flow','How it works']];
let active='registration',pid=1;const fresh=()=>({verified:false,credential:null,uploaded:false,card:false,approved:false,revoked:false,agePrepared:false,ageDocument:'Birth certificate',submitted:false,lastSubmission:null,issuer:'',repository:'',handoffs:[],events:[]});let states={1:fresh(),2:fresh()};const state=()=>states[pid];
const chip=(s,c='')=>`<span class="pill ${c}">${s}</span>`;
const btn=(label,action,light=false)=>`<button class="btn ${light?'light':''}" onclick="${action}">${label}</button>`;
function log(msg){state().events.unshift({msg,time:new Date().toLocaleTimeString([],{hour:'2-digit',minute:'2-digit'})})}
function toast(s){document.getElementById('toast').innerHTML=`<div class="toast" role="status">${s}</div>`;setTimeout(()=>document.getElementById('toast').innerHTML='',3500)}
function go(id){active=id;render();window.scrollTo({top:0,behavior:'smooth'})}
function player(n){pid=n;document.getElementById('playerNum').textContent=n;document.getElementById('playerName').textContent='Sample player '+n;document.querySelectorAll('.switch button').forEach((x,i)=>x.classList.toggle('sel',i+1===n));render()}
function resetDemo(){states={1:fresh(),2:fresh()};familyTools={verification:'State association / existing platform',storage:'Box'};closePanel();go('registration');toast('Sample state reset. No account data was changed.')}
const titles={overview:['Your family. Locked In.','One place to manage player verification, health documents and payment permissions.'],verification:['Share proof. Keep it personal.','Confirm an eligibility requirement without sending another copy of your child’s document.'],health:['The right information. Safely shared.','Keep health documents organized by player and choose who can access each item.'],payments:['Ready to pay. Always in control.','A saved payment method is separate from permission to charge it.'],access:['You decide who gets access.','Review each request, share only what is needed and manage existing permissions.'],activity:['A clear record of every action.','See the sample actions taken for this player during your walkthrough.'],workflow:['One experience. Three distinct paths.','A proposed workflow that keeps the parent in control and specialist providers responsible for their role.']};
function render(){let s=state();document.getElementById('nav').innerHTML=navs.filter(n=>['parentprofile','playerprofile','registration','tools','activity','workflow'].includes(n[0])).map(([id,i,n])=>`<button class="${active===id?'active':''}" onclick="go('${id}')" ${active===id?'aria-current="page"':''}>${icon(i)}${n}</button>`).join('');document.getElementById('title').textContent=titles[active][0];document.getElementById('intro').textContent=titles[active][1];document.getElementById('tag').innerHTML=icon('lock')+' LOCKED IN / '+navs.find(n=>n[0]===active)[2];document.getElementById('content').innerHTML=views[active](s);document.querySelector('.playerbar').style.display=active==='parentprofile'?'none':'flex'}
function summaryCard(i,status,title,desc,label,dest){return `<article class="card"><div class="cardtop"><div class="iconbox">${icon(i)}</div>${status}</div><h2>${title}</h2><p>${desc}</p><button class="textbtn" onclick="go('${dest}')">${label} →</button></article>`}
function request(s){return `<div class="card request"><div class="clubicon">CLUB</div><div><h3>Sample regional club</h3><p>Season registration · Requests eligibility confirmation and a medical clearance</p><div style="margin-top:8px">${s.approved?chip('Access approved'):s.revoked?chip('Access removed','gray'):chip('Needs your review','amber')}</div></div>${btn(s.approved?'Manage access':'Review request',"openPanel('request')",s.approved)}</div>`}
function notice(text){return `<div class="note">${icon('lock')}<div>${text}</div></div>`}
const views={
overview:s=>`<div class="summary">${summaryCard('shield',s.verified?chip('Sample check complete'):chip('Not started','gray'),'Age eligibility',s.verified?'Eligible for the sample date window. The document is not shared.':'Complete a provider check, then share only the required result.',s.verified?'View confirmation':'Start verification','verification')}${summaryCard('doc',chip(s.uploaded?'1 sample document':'No documents','gray'),'Health documents','Private records, clearance dates and carefully selected access.','Open documents','health')}${summaryCard('card',chip(s.card?'Test method saved':'Not set up','gray'),'Payment methods','Card details stay with the processor. Charges require permission.','Manage payments','payments')}</div><div class="sectiontitle"><h2>Requests for this player</h2><span>1 sample club</span></div>${request(s)}<div class="two"><div class="card"><h3 class="smalltitle">What the club receives</h3><div class="row">${icon('shield')}<div><strong>Eligibility confirmation</strong><div class="sub">Result, issuer, date and reference</div></div></div><div class="row">${icon('doc')}<div><strong>Only the health information you allow</strong><div class="sub">Clearance can be shared separately from other records</div></div></div><div class="row">${icon('card')}<div><strong>Payment status</strong><div class="sub">No full card details or unrestricted charging rights</div></div></div></div><div class="card"><h3 class="smalltitle">Designed around your family</h3><ul class="bullets"><li>Separate records for each player</li><li>Explicit approval for each purpose</li><li>Time-limited sharing</li><li>Reviewable activity history</li><li>Access removal from one place</li></ul><button class="textbtn" onclick="go('workflow')" style="font-size:12px">Explore the proposed workflow →</button></div></div>${notice('<strong>Concept, not a live vault.</strong> All checks, files and payments here are simulated. Vendor capabilities, licensing and club acceptance must be confirmed before a pilot with real data.')}`,
verification:s=>`<div class="steps"><div class="step done">01 · Choose requirement</div><div class="step ${s.verified?'done':''}">02 · Provider checks</div><div class="step ${s.verified?'done':''}">03 · Share result</div></div><div class="card center"><div class="bigicon">${icon('shield')}</div>${chip(s.verified?'SIMULATED · eligible':'SAMPLE REQUIREMENT','gray')}<h2>${s.verified?'Eligibility confirmation ready':'Verify this player’s age eligibility'}</h2><p>${s.verified?'This demonstrates a provider result, not a real identity check. Nothing has been sent to a club.':'A proposed parent-led flow checks accepted evidence with a verification provider. This prototype uses a preconfigured sample result.'}</p>${btn(s.verified?'Review what can be shared':'Try sample verification',s.verified?"openPanel('proof')":"openPanel('verify')")}<div class="legal">No ID upload or camera access in this prototype.</div></div><div class="two"><div class="card"><h3 class="smalltitle">Example eligibility rule</h3><div class="kv"><div><span>Competition</span><strong>Sample youth competition</strong></div><div><span>Season</span><strong>2026–27 · example only</strong></div><div><span>Accepted birth-date window</span><strong>Jan 1–Dec 31, 2013</strong></div><div><span>Provider</span><strong>${s.issuer || familyTools.verification} · candidate</strong></div></div><p class="legal">The club or governing body supplies the actual eligibility rules. These dates are illustrative.</p></div><div class="card"><h3 class="smalltitle">The proposed data boundary</h3><ul class="bullets"><li>Evidence goes directly to the verification provider</li><li>Soccer Center receives a minimal result</li><li>Club receives it only with approval</li><li>Provider retention and exception handling need agreement</li></ul></div></div>`,
health:s=>`<div class="sectiontitle" style="margin-top:0"><h2>Player documents</h2>${btn('＋ Add sample document',"openPanel('upload')")}</div><div class="card">${s.uploaded?`<div class="row"><div class="iconbox">${icon('doc')}</div><div><strong>Sample medical clearance.pdf</strong><div class="sub">Synthetic file · Example expiry: June 30, 2027</div></div><div class="right">${chip('Parent-managed','gray')}${btn('View',"openPanel('document')",true)}</div></div>`:`<div class="empty"><div class="bigicon">${icon('doc')}</div><strong>No health documents yet</strong><p>Add a synthetic medical clearance to try the workflow.</p></div>`}</div><div class="two"><div class="card"><h3 class="smalltitle">Keep categories separate</h3><ul class="bullets"><li>Participation clearance</li><li>Emergency instructions</li><li>Allergy or medication information</li><li>Other private records</li></ul><p class="legal">A clearance request should not reveal the rest of a player’s health history.</p></div><div class="card"><h3 class="smalltitle">Repository: ${s.repository || familyTools.storage} · candidate</h3><p class="sub">Documents would live in a configured private repository. Soccer Center would retain references and access settings.</p><p class="legal">Licensing, account administration, health-data requirements and audit coverage remain to be validated. No storage connection is active. Existing sample documents keep the repository recorded when they were added.</p></div></div>${notice('Removing access prevents future access through the system. It cannot recall a file already downloaded or a screenshot. Storage ownership and administrator access must be defined in the pilot agreement.')}`,
payments:s=>`<div class="sectiontitle" style="margin-top:0"><h2>Saved payment methods</h2>${btn(s.card?'Manage test method':'＋ Add test method',"openPanel('payment')")}</div><div class="card">${s.card?`<div class="row"><div class="iconbox">${icon('card')}</div><div><strong>Test card ···· 4242</strong><div class="sub">Demonstration only · No card was collected</div></div><div class="right">${chip('Test mode','gray')}${btn('Remove',"removeCard()",true)}</div></div>`:`<div class="empty"><div class="bigicon">${icon('card')}</div><strong>No payment method saved</strong><p>Try the simulated processor handoff. No card details are requested.</p></div>`}</div><div class="two"><div class="card"><h3 class="smalltitle">How a future payment would work</h3><ol class="bullets"><li>Club provides an agreed payment request</li><li>You review the merchant, amount and purpose</li><li>You authorize payment through the processor</li><li>The club receives payment status</li></ol><p class="legal">Saving a card does not authorize future charges.</p></div><div class="card"><h3 class="smalltitle">What stays out of Soccer Center</h3><ul class="bullets"><li>Full card number</li><li>Card security code / CVV</li><li>Card images or scans</li></ul><p class="legal">A licensed processor would hold the payment method. Soccer Center would retain its reference and permitted display details.</p></div></div>${notice('<strong>Payment integrations are not interchangeable.</strong> A saved method cannot automatically pay any PlayMetrics or TeamSnap merchant. Provider support, merchant agreements and consent must be established.')}`,
access:s=>`<div class="sectiontitle" style="margin-top:0"><h2>Club requests</h2><span>Approval is specific to each item</span></div>${request(s)}<div class="sectiontitle"><h2>Active access</h2></div><div class="card">${s.approved?`<div class="row"><div class="clubicon">CLUB</div><div><strong>Sample regional club · Registration reviewer</strong><div class="sub">${(s.share||[]).join(' + ')} · Until example season end</div></div><div class="right">${btn('Remove access',"revoke()",true)}</div></div>`:`<div class="empty">No active sharing permissions for this sample player.</div>`}</div>${notice('No parent password, full card number or unrestricted vault access is shared. A real integration would require the receiving club or platform to accept the verification result and enforce the agreed permissions.')}`,
activity:s=>`<div class="card"><h3 class="smalltitle">Prototype activity · Sample player ${pid}</h3>${s.events.length?`<div class="tablewrap"><table class="table"><thead><tr><th>Action</th><th>Actor</th><th>Time</th></tr></thead><tbody>${s.events.map(e=>`<tr><td>${e.msg}</td><td>Demo parent</td><td>${e.time}</td></tr>`).join('')}</tbody></table></div>`:`<div class="empty">Try verification, add a sample document or review a request to see the activity here.</div>`}<p class="legal">This is a temporary walkthrough log, not a production audit system. It resets when the page reloads.</p></div>`,
workflow:s=>`<div class="two" style="margin-top:0"><div class="card" style="padding:27px"><div class="flow"><div class="flowitem"><h3>1. Sign in and select a player</h3><p>Authenticate the parent. Apply player-specific access rules. Step-up authentication for sensitive actions is a proposed requirement.</p></div><div class="flowitem"><h3>2. Meet the registration requirements</h3><p>Use a verification provider for age evidence, a document repository for health files and a payment processor for cards.</p></div><div class="flowitem"><h3>3. Review a club’s request</h3><p>See the recipient, purpose, requested items and access period before approving.</p></div><div class="flowitem"><h3>4. Share only what is needed</h3><p>Send an accepted eligibility result, grant access to selected health information and authorize payments separately.</p></div><div class="flowitem"><h3>5. Review and manage over time</h3><p>Track activity, replace expired documents, withdraw permissions and manage deletion/export requests.</p></div></div></div><div><div class="card"><h3 class="smalltitle">Soccer Center coordinates</h3><p class="sub">Player mapping, requests, parent approvals, status displays and the connected experience.</p><h3 class="smalltitle" style="margin-top:23px">Specialist services provide</h3><ul class="bullets"><li>Evidence verification</li><li>Protected content storage</li><li>Payment-method vaulting and processing</li></ul></div><div class="note">${icon('shield')}<div><strong>Pilot acceptance gates</strong><br>Vendor support and licensing · Child/guardian evidence support · Security review · Cross-family isolation · Club acceptance · Data retention and deletion · Payment merchant model</div></div></div></div>`};
function openPanel(type){let s=state(),body='';if(type==='verify')body=`<h2>Try an age check</h2><div class="pill gray">${familyTools.verification} · candidate provider</div><p>Evidence route to evaluate: birth certificate or passport. Child/guardian support, accepted documents and authenticity checks require vendor confirmation. National Sports ID uses human-confirmed review rather than a fully unattended check.</p><p>In a live flow, a specialist provider would collect and validate accepted evidence. No documents leave your device in this prototype because no upload occurs.</p><div class="card"><h3 class="smalltitle">Simulated outcome</h3><p class="sub">Sample player ${pid} meets the illustrative birth-date window. This is preconfigured, not a real check.</p></div><div class="panelactions">${btn('Simulate successful check',"verify()")}</div><p class="legal">Unclear or failed evidence would remain incomplete, with an agreed exception path. Facial age estimation alone would not establish an exact youth eligibility date.</p>`;
if(type==='proof')body=`<h2>Eligibility confirmation</h2><p>Proposed minimal result shown to an approved recipient.</p><div class="card"><div class="kv"><div><span>Player</span><strong>Sample player ${pid}</strong></div><div><span>Result</span><strong>Eligible · simulated</strong></div><div><span>Issuer</span><strong>${s.issuer || familyTools.verification} · simulated</strong></div><div><span>Reference</span><strong>DEMO-P${pid}-AGE</strong></div><div><span>Purpose</span><strong>Sample competition</strong></div><div><span>Validity</span><strong>Example season only</strong></div></div></div>${notice('No birth certificate, full date of birth or document image is included in this proposed confirmation. The result is still player-linked personal information.')}<div class="panelactions">${btn('Review club request',"openPanel('request')")}</div>`;
if(type==='upload')body=`<h2>Add a health document</h2><div class="pill gray">${familyTools.storage} · candidate repository</div><p>This demonstrates document organization. Do not upload real health information to a prototype.</p><div class="card center"><div class="bigicon">${icon('doc')}</div><strong>Sample medical clearance.pdf</strong><p class="sub">A synthetic placeholder will be added. No file picker, upload or external storage connection.</p></div><label class="label">Category<select class="select" disabled><option>Participation clearance</option></select></label><div class="panelactions">${btn('Add synthetic document',"upload()")}</div>`;
if(type==='document')body=`<h2>Sample medical clearance</h2><p>Synthetic placeholder · Sample player ${pid}</p><div class="card center"><div class="bigicon">${icon('doc')}</div><h3 class="smalltitle">Medical participation clearance</h3><div class="sub">Sample repository: ${s.repository || familyTools.storage}</div><p>DEMONSTRATION DOCUMENT<br>No medical assessment was performed.<br>No actual health information is present.</p>${chip('Example expiry · Jun 30, 2027','gray')}</div><div class="panelactions">${btn('Review sharing options',"openPanel('request')")}</div>`;
if(type==='payment')body=`<h2>Save a payment method</h2><p>A live implementation would hand off to a payment provider’s hosted collection interface.</p><div class="card center"><div class="bigicon">${icon('card')}</div><strong>Processor handoff · simulated</strong><p>No card-number fields are provided. Use the button below to add a fictional test method.</p></div><label class="option"><input id="payconsent" type="checkbox" onchange="document.getElementById('savepay').disabled=!this.checked"><span><strong>Simulate consent to save a method</strong><small>For future parent-authorized payments. This does not authorize a charge or create a real mandate.</small></span></label><div class="panelactions"><button class="btn" id="savepay" disabled onclick="saveCard()">Save test method ···· 4242</button></div>`;
if(type==='request')body=`<h2>Review club request</h2><p><strong>Sample regional club</strong><br>Registration reviewer · Sample season registration</p><div class="card"><label class="option"><input type="checkbox" id="shareage" ${s.verified?'':'disabled'}><span><strong>Age eligibility confirmation</strong><small>${s.verified?'Result, issuer, validity and player reference. No identity document.':'Complete the sample age check first.'}</small></span></label><label class="option"><input type="checkbox" id="sharehealth" ${s.uploaded?'':'disabled'}><span><strong>Medical participation clearance</strong><small>${s.uploaded?'Preview access to this selected sample document only.':'Add a synthetic clearance document first.'}</small></span></label><div class="option">${icon('card')}<span><strong>No payment authorization requested</strong><small>Payment approval is a separate action. This request cannot charge your saved method.</small></span></div></div><label class="label">Proposed access period<select class="select" disabled><option>Until sample season end · June 30, 2027</option></select></label><p class="legal">This prototype records your selection only. No information is sent. Live recipient identity, expiry enforcement and audit events require implementation.</p><div class="panelactions">${btn('Approve selected items',"approve()")}${btn('Not now',"closePanel()",true)}</div>`;
document.getElementById('overlay').innerHTML=`<div class="modalback" onclick="if(event.target===this)closePanel()"><section class="panel" role="dialog" aria-modal="true" aria-label="${type}"><div class="panelhead"><div class="eyebrow">Locked In · Sample player ${pid}</div><button class="close" aria-label="Close dialog" onclick="closePanel()">×</button></div>${body}</section></div>`;document.body.style.overflow='hidden';document.querySelector('.close').focus()}
function closePanel(){document.getElementById('overlay').innerHTML='';document.body.style.overflow=''}
function verify(){recordDemoVerification('verified');closePanel();render()}
function upload(){state().uploaded=true;state().repository=familyTools.storage;log('Synthetic medical clearance added');closePanel();render();toast('Sample document added. No file was uploaded.')}
function saveCard(){state().card=true;log('Test payment method saved with simulated consent');closePanel();render();toast('Test method added. No card data was collected.')}
function removeCard(){state().card=false;log('Test payment method removed');render();toast('Test method removed')}
function approve(){const items=[];if(document.getElementById('shareage').checked)items.push('Eligibility result');if(document.getElementById('sharehealth').checked)items.push('Medical clearance');if(!items.length){toast('Select an available item, or complete its sample setup first.');return}state().share=items;state().approved=true;state().revoked=false;log('Sample club access approved: '+items.join(', '));closePanel();render();toast('Sample permission recorded. Nothing was shared externally.')}
function revoke(){state().approved=false;state().revoked=true;log('Sample club access removed');render();toast('Sample access removed')}

titles.parentprofile=['Your family’s soccer workspace.','Locked In lives within your parent profile, with a private record for each player and explicit approval before any external handoff.'];
titles.playerprofile=['Your player. Their private record.','Verification, health information and registration handoffs sit alongside the player profile.'];
titles.integrations=['Ready for the next registration.','Choose a destination, review the player mapping and approve the minimum information to share.'];
views.parentprofile=s=>`<div class="card" style="background:linear-gradient(120deg,#193b65,#2c5a96);color:white;padding:29px"><div class="eyebrow" style="color:#c2d4ed">PARENT PROFILE</div><h2 style="font-size:27px;margin:8px 0">Your soccer family</h2><p style="color:#d4e0ef;margin:0;min-height:0">Demo parent · Private workspace · No real account information</p></div><div class="sectiontitle"><h2>Locked In · Family overview</h2><span>Embedded in your profile</span></div><div class="summary">${summaryCard('shield',chip('Player-specific','gray'),'Verification','Age evidence is checked by a proposed specialist provider.','Open player verification','verification')}${summaryCard('doc',chip('Selected access','gray'),'Health documents','Keep each player’s documents and permissions separate.','Manage documents','health')}${summaryCard('card',chip('Separate consent','gray'),'Payments','Saved processor methods and authorizations remain distinct.','Manage methods','payments')}</div><div class="sectiontitle"><h2>My players</h2><span>Select a player to manage their record</span></div><div class="two" style="margin-top:0">${[1,2].map(n=>`<div class="card"><div class="row" style="padding-top:0"><div class="avatar">P${n}</div><div><strong>Sample player ${n}</strong><div class="sub">Parent-managed · Private profile</div></div></div><div style="margin:15px 0;display:flex;gap:7px;flex-wrap:wrap">${chip(states[n].verified?'Sample age check complete':'Age check not started',states[n].verified?'':'gray')}${chip(states[n].uploaded?'Clearance added':'No clearance','gray')}</div>${btn('Open player profile',`openPlayer(${n})`,true)}</div>`).join('')}</div>${notice('<strong>Family-level oversight; player-level permissions.</strong> Start from your parent profile, then select a player before sharing a result or health document. Verification evidence and health records do not automatically pass to a registration platform.')}`;
views.playerprofile=s=>`<div class="card"><div class="eyebrow">PLAYER PROFILE · SAMPLE DATA</div><h2 style="font-size:26px;margin:9px 0 5px">Sample player ${pid}</h2><p style="min-height:0">Club, team, calendar and game statistics would remain in the existing player profile.</p><div style="display:flex;gap:10px;flex-wrap:wrap">${chip('Private profile','gray')}${chip('Parent-managed','gray')}</div></div><div class="sectiontitle"><h2>Locked In · This player</h2><span>Verification & registration readiness</span></div><div class="summary">${summaryCard('shield',s.verified?chip('Simulated · complete'):chip('Not started','gray'),'Age eligibility','Birth certificate / passport support must be confirmed with the selected provider.','Manage verification','verification')}${summaryCard('doc',chip(s.uploaded?'Sample clearance added':'Not added','gray'),'Health documents','Approve selected documents independently from eligibility proof.','Open documents','health')}${summaryCard('card',chip(s.card?'Test method available':'No test method','gray'),'Payments','Payment authorization is independent of verification sharing.','Manage payment method','payments')}</div><div class="sectiontitle"><h2>Registration handoff</h2><span>Future integration</span></div><div class="card request"><div class="clubicon">↗</div><div><h3>Send verification to PlayMetrics or TeamSnap</h3><p>Review the destination, player mapping and exact proof before approval.</p><div style="margin-top:9px">${chip('Concept · not connected','amber')}</div></div>${btn('Review handoff',"go('integrations')")}</div>${notice('This adds an integration point to the existing player experience. It does not replace club registration, transfer full documents by default or establish governing-body approval.')}`;
views.integrations=s=>`<div class="summary">${['Sample regional club'].map(name=>`<div class="card"><div class="cardtop"><div class="iconbox">${icon('arrow')}</div>${chip('Not connected','gray')}</div><h2>${name}</h2><p>Proposed destination for an approved, player-linked eligibility confirmation.</p>${btn('Preview handoff',`openHandoff('${name}')`,true)}</div>`).join('')}</div><div class="sectiontitle"><h2>Handoff history · This player</h2></div><div class="card">${s.handoffs.length?s.handoffs.map(h=>`<div class="row">${icon('shield')}<div><strong>${h.destination}</strong><div class="sub">${h.scope.join(' + ')} · Sample player ${pid}</div></div><div class="right">${chip('Simulated only','amber')}</div></div>`).join(''):'<div class="empty">No handoffs simulated. Complete the sample age check, then preview a destination.</div>'}</div>${notice('<strong>Integration and acceptance are pending.</strong> API access, recipient identity, player mapping, association recognition and data-sharing terms must be agreed. An approval in this prototype sends nothing to any vendor. Payment credentials are never included.')}`;
function openPlayer(n){player(n);go('playerprofile')}
let pendingDestination='';
function openHandoff(destination){pendingDestination=destination;const s=state();document.getElementById('overlay').innerHTML=`<div class="modalback" onclick="if(event.target===this)closePanel()"><section class="panel" role="dialog" aria-modal="true" aria-label="Review verification handoff"><div class="panelhead"><div class="eyebrow">REGISTRATION HANDOFF · CONCEPT</div><button class="close" aria-label="Close dialog" onclick="closePanel()">×</button></div><h2>Send to ${destination}</h2><p>Review what would be shared. This preview does not connect to ${destination}.</p><div class="card"><div class="kv"><div><span>Soccer Center player</span><strong>Sample player ${pid}</strong></div><div><span>External player reference</span><strong>DEMO-EXTERNAL-P${pid}</strong></div><div><span>Club / competition</span><strong>Sample regional club</strong></div><div><span>Governing-body recognition</span><strong>Not approved · POC only</strong></div></div><p class="legal">Production must confirm an authorized match to the recipient’s player record. A parent selection alone is not identity proof.</p></div><label class="option"><input type="checkbox" id="handoffage" ${s.verified?'checked':'disabled'}><span><strong>Eligibility confirmation</strong><small>${s.verified?'Simulated result, issuer, rule reference, verification date and validity. No birth certificate, passport or full date of birth.':'Complete the sample age check before sharing a confirmation.'}</small></span></label><label class="option"><input type="checkbox" id="handoffhealth" ${s.uploaded?'':'disabled'}><span><strong>Selected medical clearance access</strong><small>${s.uploaded?'Optional and separate. A future time-limited, recipient-authorized access grant; no full medical history.':'Add a sample clearance to explore this optional access grant.'}</small></span></label><div class="option">${icon('card')}<span><strong>No payment data or charging permission</strong><small>Payments require a separate processor-supported workflow.</small></span></div><label class="option"><input type="checkbox" id="handoffconsent"><span><strong>I confirm the sample destination and player mapping</strong><small>Permission is limited to the selected purpose and sample season. Nothing leaves this prototype.</small></span></label><div class="panelactions">${btn('Simulate approved handoff',"simulateHandoff()")}${btn('Cancel',"closePanel()",true)}</div><p class="legal">A production handoff would track pending, accepted, rejected, expired and withdrawn states. Removing future access cannot recall already received data or independently retained records.</p></section></div>`;document.body.style.overflow='hidden';document.querySelector('.close').focus()}
function simulateHandoff(){const scope=[];if(document.getElementById('handoffage').checked&&state().verified)scope.push('Eligibility confirmation');if(document.getElementById('handoffhealth').checked&&state().uploaded)scope.push('Selected clearance access');if(!scope.length){toast('Complete sample setup and select an available item.');return}if(!document.getElementById('handoffconsent').checked){toast('Confirm the sample recipient and player mapping.');return}state().handoffs.unshift({destination:pendingDestination,scope});log('Simulated handoff to '+pendingDestination+': '+scope.join(', '));closePanel();render();toast('Handoff simulated. No data was sent to '+pendingDestination+'.')}


let familyTools={verification:'State association / existing platform',storage:'Box'};
const providerInfo={Yoti:{text:'Document-based age checks and digital ID. Confirm birth-certificate support, minors’ workflows and exact birth-date-window decisions.',url:'https://developers.yoti.com/age-verification/doc-scan'},Veriff:{text:'Age validation using date of birth from identity evidence. Confirm supported child documents, parental flows and competition-rule evaluation.',url:'https://www.veriff.com/product/age-validation'},Persona:{text:'Configurable age assurance with government-ID checks. Confirm birth-certificate validation, child-to-document matching and minimal-result delivery.',url:'https://help.withpersona.com/articles/5I4utwPPHF4TilUvZTJCsh/'}};
const repositoryInfo={Box:{text:'Content APIs and embedded UI components. Evaluate external-user licensing, permissions, health-data terms and storage administration.',url:'https://developer.box.com/guides'},Egnyte:{text:'File-management APIs for custom applications. Evaluate embedded experience, external-family licensing, health-data terms and access isolation.',url:'https://developers.egnyte.com/integration/cfs/api-docs/getting-started'}};
titles.tools=['Choose the tools behind the experience.','Candidate providers for a POC—not existing partnerships, live connections or approved integrations.'];
views.tools=s=>`<div class="two" style="margin-top:0"><div class="card"><div class="cardtop"><div class="iconbox">${icon('shield')}</div>${chip('Under evaluation','amber')}</div><h2>Age verification tool</h2><label class="label">Candidate provider<select class="select" onchange="chooseTool('verification',this.value)">${Object.keys(providerInfo).map(n=>`<option ${familyTools.verification===n?'selected':''}>${n}</option>`).join('')}</select></label><p style="min-height:65px">${providerInfo[familyTools.verification].text}</p><a href="${providerInfo[familyTools.verification].url}" target="_blank" rel="noopener" style="font-size:12px;color:var(--blue)">Provider documentation ↗</a><div class="note"><div><strong>Required evidence: birth certificate and/or passport.</strong><br>Listed capabilities do not confirm support for this exact youth-sports use case. Age estimation alone is not the proposed eligibility method.</div></div></div><div class="card"><div class="cardtop"><div class="iconbox">${icon('doc')}</div>${chip('Under evaluation','amber')}</div><h2>Private document storage</h2><label class="label">Candidate repository<select class="select" onchange="chooseTool('storage',this.value)">${Object.keys(repositoryInfo).map(n=>`<option ${familyTools.storage===n?'selected':''}>${n}</option>`).join('')}</select></label><p style="min-height:65px">${repositoryInfo[familyTools.storage].text}</p><a href="${repositoryInfo[familyTools.storage].url}" target="_blank" rel="noopener" style="font-size:12px;color:var(--blue)">Repository documentation ↗</a><div class="note"><div><strong>Documents only; no payment-card storage.</strong><br>Full card details stay with a separate payment processor. Ownership, administrator access, retention and deletion need explicit agreement.</div></div></div></div><div class="sectiontitle"><h2>Selected POC configuration</h2><span>Family-level concept settings</span></div><div class="card"><div class="row">${icon('shield')}<div><strong>${familyTools.verification} → eligibility result</strong><div class="sub">Evidence is checked through a proposed provider-led flow.</div></div></div><div class="row">${icon('doc')}<div><strong>${familyTools.storage} → private document repository</strong><div class="sub">Health documents and any agreed retained identity copy.</div></div></div><div class="row">${icon('arrow')}<div><strong>PlayMetrics / TeamSnap → approved handoff</strong><div class="sub">Recipient API access and governing-body acceptance remain pending.</div></div></div><div style="margin-top:20px;display:flex;gap:10px;flex-wrap:wrap">${btn('Try verification',"go('verification')")}${btn('Open health documents',"go('health')",true)}</div></div>${notice('Selectors are for evaluating the POC design. They do not provision services, transfer documents or move existing records. New sample checks and documents record the selected provider; previous results retain their original issuer/repository.')}`;
function chooseTool(kind,value){const choices=kind==='verification'?providerInfo:repositoryInfo;if(!Object.prototype.hasOwnProperty.call(choices,value))return;familyTools[kind]=value;render();toast('Candidate selected for new sample actions only.')}
const originalParentView=views.parentprofile;views.parentprofile=s=>originalParentView(s)+`<div class="sectiontitle"><h2>Tools behind your private workspace</h2></div><div class="card request"><div class="iconbox">${icon('grid')}</div><div><h3>${familyTools.verification} + ${familyTools.storage}</h3><p>Candidate verification and storage tools · no live connection</p></div>${btn('Choose POC tools',"go('tools')",true)}</div>`;


providerInfo['GotSport']={text:'Candidate connection to an existing registration and association-review workflow. Parent-authorized API access, verification-status retrieval, SSO and embedding require confirmation. No live connection.',url:'https://system.gotsport.com/'};
providerInfo['National Sports ID']={text:'Youth-sports age and grade review using birth certificates or passports, with AI-assisted analysis and human-confirmed review. Issues a typically annual Sports ID. API access, minimal-result sharing and soccer-association recognition require agreement; not connected.',url:'https://www.nationalsportsid.com/sports-age-and-grade-verification/'};
titles.registration=['Reusable onboarding. Less repeat work.','Parent-led details and verification, a quick club prerequisite review, then a club-owned handoff to its existing software. Explore the proposed journey with sample data.'];
const requirements=s=>Number(s.verified)+Number(s.uploaded)+Number(s.card);
views.registration=s=>`<div class="card" style="padding:17px 20px;margin-bottom:18px"><div class="cardtop"><div><strong style="font-size:14px">Sample player ${pid} · Registration checklist</strong><div class="sub">All three items are required for this POC.</div></div>${chip(`${requirements(s)} / 3 ready`,requirements(s)===3?'':'gray')}</div><div style="height:5px;background:#e7edf5;border-radius:5px;margin-top:14px"><div style="height:5px;border-radius:5px;background:var(--blue);width:${requirements(s)/3*100}%"></div></div></div><div class="card" style="margin-bottom:18px"><div class="eyebrow">POC TOOL SELECTION · NO LIVE CONNECTION</div><div class="two" style="margin-top:10px;gap:18px"><label class="label" style="margin:0">Age verification<select class="select" onchange="chooseTool('verification',this.value)">${Object.keys(providerInfo).map(n=>`<option ${familyTools.verification===n?'selected':''}>${n}</option>`).join('')}</select></label><label class="label" style="margin:0">Private document storage<select class="select" onchange="chooseTool('storage',this.value)">${Object.keys(repositoryInfo).map(n=>`<option ${familyTools.storage===n?'selected':''}>${n}</option>`).join('')}</select></label></div><p class="legal"><strong>${familyTools.verification}:</strong> ${providerInfo[familyTools.verification].text}</p><p class="legal">Candidates only. Document support, child workflows, licensing and club acceptance require confirmation. No live service is connected.</p></div><div class="summary">${requirementCard(1,'shield','Age evidence',s.verified,'Prepare evidence, then check the result','Preparing a sample document is separate from verification. Association acceptance is tracked below.',`<label class="label" style="margin:14px 0">Sample document type<select class="select" onchange="setAgeDocument(this.value)"><option ${s.ageDocument==='Birth certificate'?'selected':''}>Birth certificate</option><option ${s.ageDocument==='Passport'?'selected':''}>Passport</option></select></label>${btn(s.agePrepared?'Replace sample evidence':'＋ Add sample age document',"prepareAge()",s.agePrepared)}`)}${requirementCard(2,'doc','Health document',s.uploaded,'Participation clearance','A selected document is stored privately. This does not verify medical fitness or grant access to a full health history.',`<div class="sub" style="margin:14px 0">${s.uploaded?'Sample medical clearance.pdf':'Synthetic medical clearance · no upload'}</div>${btn(s.uploaded?'Replace sample clearance':'＋ Add sample health document',"prepareHealth()",s.uploaded)}`)}${requirementCard(3,'card','Payment method',s.card,'Saved with a payment processor','Card details belong in a payment provider’s vault. No card image, full number or CVV is stored in the document repository.',`<div class="sub" style="margin:14px 0">${s.card?'Test method ···· 4242':'Simulated hosted card setup · no charge'}</div>${btn(s.card?'Replace test method':'＋ Set up test payment method',"preparePayment()",s.card)}`)}</div><div class="sectiontitle"><h2>Review & submit</h2><span>Stay on this page</span></div><div class="card"><div class="two" style="margin-top:0"><label class="label" style="margin:0">Parent-authorized recipient<select class="select" id="packageDestination"><option>Sample regional club</option></select></label><div><div class="sub">Player mapping</div><strong style="font-size:13px">Sample player ${pid} → DEMO-EXTERNAL-P${pid}</strong><p class="legal" style="margin-top:5px">Placeholder mapping only; no vendor account connected.</p></div></div><div class="row"><div class="iconbox">${icon('shield')}</div><div><strong>Age verification → ${s.issuer || familyTools.verification}</strong><div class="sub">Birth-date eligibility check; original evidence is not sent to the club.</div></div></div><div class="row"><div class="iconbox">${icon('doc')}</div><div><strong>Health clearance → ${familyTools.storage}</strong><div class="sub">Only the selected clearance would be accessible to an authorized recipient.</div></div></div><div class="row"><div class="iconbox">${icon('card')}</div><div><strong>Payment method → specialist processor</strong><div class="sub">No card data is sent to the age verifier or document repository. No charge is authorized.</div></div></div><label class="option"><input type="checkbox" id="packageAgeConsent" onchange="packageButton()"><span><strong>Approve the age check and eligibility-result sharing</strong><small>For the selected player, destination and sample competition only.</small></span></label><label class="option"><input type="checkbox" id="packageHealthConsent" onchange="packageButton()"><span><strong>Approve access to the selected health clearance</strong><small>For the sample registration purpose, until the example season end. Other health records remain private.</small></span></label><label class="option"><input type="checkbox" id="packagePaymentConsent" onchange="packageButton()"><span><strong>Approve saving the test payment method</strong><small>Future charges would need a separate merchant-supported authorization. Confirming this package does not authorize payment.</small></span></label><label class="option"><input type="checkbox" id="packageMappingConsent" onchange="packageButton()"><span><strong>Confirm the sample player and destination mapping</strong><small>This demonstration does not establish vendor connectivity or association approval.</small></span></label><div style="margin-top:22px;display:flex;align-items:center;gap:16px;flex-wrap:wrap"><button class="btn" id="packageSubmit" disabled onclick="submitPackage()">Submit sample package</button><span class="sub">Complete all 3 items and approvals above.</span></div></div>${s.submitted?`<div class="card" role="status" style="margin-top:18px;border-color:#a8cbb8;background:#f1f8f4"><div class="cardtop"><h3 class="smalltitle" style="margin:0">Sample submission complete</h3>${chip('Simulated only')}</div><p class="sub" style="margin-bottom:0">${s.lastSubmission.destination} · Sample player ${pid}<br>Age check: ${s.lastSubmission.issuer} · Synthetic clearance: ${s.lastSubmission.repository} · Test method: saved<br>No documents, identity checks, payments or external transfers took place.</p></div>`:''}${notice('<strong>One submission, separate purposes.</strong> This POC groups the steps; it does not send all three items to an age-verification service. Selecting or replacing any sample item requires reviewing approvals again.')}`;
function requirementCard(n,i,title,ready,subtitle,desc,action){return `<section class="card" style="display:block"><div class="cardtop"><div class="iconbox">${icon(i)}</div>${chip(ready?'Sample ready':'Required',ready?'':'amber')}</div><h2>${n}. ${title}</h2><div class="sub" style="font-weight:650;margin-bottom:10px">${subtitle}</div><p style="min-height:80px">${desc}</p>${action}</section>`}
function setAgeDocument(value){if(!['Birth certificate','Passport'].includes(value))return;state().ageDocument=value;state().verified=false;state().credential=null;state().agePrepared=false;state().submitted=false;render()}
function prepareAge(){state().approved=false;state().share=[];state().verified=false;state().credential=null;state().agePrepared=true;state().submitted=false;log('Sample '+state().ageDocument.toLowerCase()+' prepared for registration');render();toast('Synthetic age evidence added. No document was uploaded.')}
function prepareHealth(){state().uploaded=true;state().submitted=false;state().repository=familyTools.storage;log('Synthetic health clearance prepared');render();toast('Sample clearance added. No file was uploaded.')}
function preparePayment(){state().card=true;state().submitted=false;log('Test payment-method setup prepared');render();toast('Processor setup simulated. No card data was collected.')}
function packageConsents(){return ['packageAgeConsent','packageHealthConsent','packagePaymentConsent','packageMappingConsent'].every(id=>document.getElementById(id)?.checked)}
function packageButton(){document.getElementById('packageSubmit').disabled=!(requirements(state())===3&&packageConsents())}
function submitPackage(){const s=state();if(requirements(s)!==3||!packageConsents()){toast('Complete all three requirements and review the approvals.');return}const destination=document.getElementById('packageDestination').value;if(!['Sample regional club'].includes(destination))return;s.repository=familyTools.storage;s.approved=true;s.revoked=false;s.share=['Eligibility result','Selected medical clearance'];s.handoffs.unshift({destination,scope:['Eligibility result','Selected clearance access']});s.submitted=true;s.lastSubmission={destination,issuer:s.issuer,repository:s.repository};log('Sample package submitted to '+destination+'; age check, clearance access and saved-method consent simulated');render();toast('Sample package complete. Nothing was sent externally.')}
views.parentprofile=s=>`<div class="card" style="background:linear-gradient(120deg,#193b65,#2c5a96);color:white;padding:29px"><div class="eyebrow" style="color:#c2d4ed">PARENT PROFILE</div><h2 style="font-size:27px;margin:8px 0">Your soccer family</h2><p style="color:#d4e0ef;margin:0;min-height:0">Demo parent · Private workspace · Sample data only</p></div><div class="sectiontitle"><h2>Locked In · Registration readiness</h2><span>One checklist per player</span></div><div class="two" style="margin-top:0">${[1,2].map(n=>`<div class="card"><div class="row" style="padding-top:0"><div class="avatar">P${n}</div><div><strong>Sample player ${n}</strong><div class="sub">Private · Parent-managed</div></div></div><h2>${requirements(states[n])} of 3 requirements ready</h2><p>Age evidence · Health clearance · Payment method</p>${chip(states[n].submitted?'Sample package submitted':'Ready to complete','gray')}<div style="margin-top:17px">${btn('Complete registration',`openRegistration(${n})`)}</div></div>`).join('')}</div>${notice('Each player has one checklist, one review and one sample submission. Nothing connects to real club systems or provider accounts.')}`;
views.playerprofile=s=>`<div class="card"><div class="eyebrow">PLAYER PROFILE · PRIVATE</div><h2 style="font-size:26px;margin:9px 0">Sample player ${pid}</h2><p>Existing club, team, calendar and game information would remain here.</p></div><div class="sectiontitle"><h2>Locked In · Complete this player’s registration</h2></div><div class="card"><h2 style="margin-top:0">${requirements(s)} of 3 requirements ready</h2><div class="row">${icon('shield')}<div><strong>Age document</strong><div class="sub">${s.agePrepared?s.ageDocument+' · sample ready':'Birth certificate or passport required'}</div></div></div><div class="row">${icon('doc')}<div><strong>Health clearance</strong><div class="sub">${s.uploaded?'Synthetic document ready':'Required'}</div></div></div><div class="row">${icon('card')}<div><strong>Payment method</strong><div class="sub">${s.card?'Test setup ready':'Processor setup required'}</div></div></div><div style="margin-top:20px">${btn('Open registration checklist',"go('registration')")}</div></div>`;
function openRegistration(n){player(n);go('registration')}
views.workflow=s=>`<div class="card" style="padding:27px"><div class="flow"><div class="flowitem"><h3>Select the player</h3><p>Open Locked In from the parent or player profile.</p></div><div class="flowitem"><h3>Prepare all three requirements</h3><p>Add sample age evidence, a synthetic health clearance and a test payment method on the same page.</p></div><div class="flowitem"><h3>Review the destination and approvals</h3><p>Review the club recipient, age-result sharing, selected health-document access and saved-method consent separately. Parents submit to the club; the club owns the downstream software connection.</p></div><div class="flowitem"><h3>Submit once</h3><p>Age evidence routes to a verifier, health records to the chosen repository and card setup to a payment processor. Each retains its distinct purpose.</p></div><div class="flowitem"><h3>Receive a registration status</h3><p>The club checks all prerequisites, then passes approved fields into PlayMetrics, TeamSnap or its existing software. This backend transfer is club-owned and simulated; production requires API access, identity mapping, accepted verification and security review.</p></div></div></div>`;


// Verification is an issuer claim. Association recognition is a separate, unfulfilled gate.
providerInfo['State association / existing platform']={text:'Proposed connection to an association-issued verification status in its existing registration platform. No status feed, data-sharing agreement or acceptance is established.',url:'https://www.coloradosoccer.org/youth'};
const recognition={association:'Colorado Soccer Association',status:'pending_agreement',policyVersion:null,acceptanceReference:null};
function recordDemoVerification(status){
 if(!['verified','needs_review','expired','revoked'].includes(status))return;
 const s=state();if(!s.agePrepared){toast('Prepare sample age evidence first.');return}
 s.verified=status==='verified';s.submitted=false;s.approved=false;s.share=[];s.issuer=familyTools.verification;
 s.credential={environment:'simulation',subject:'DEMO-P'+pid,issuer:familyTools.verification,attribute:'Date of birth',status,checkedAt:new Date().toISOString(),rule:'DEMO-AGE-RULE-01',validity:'Illustrative 2026–27 season only',reference:'DEMO-P'+pid+'-AGE',recognition:'pending_agreement'};
 log('Simulated issuer result: '+status+'. State acceptance remains pending agreement.');render();toast('Demo result updated. No live check or association approval occurred.');
}
function recognitionPanel(s,controls=false){
 const c=s.credential,valid=!!(c&&c.status==='verified'&&s.verified);
 const labels={verified:'✓ Age verified · simulated',needs_review:'Needs review · simulated',expired:'Expired · simulated',revoked:'Revoked · simulated'};
 return `<section class="card recognition" aria-label="Age verification and state acceptance"><div class="cardtop"><div><div class="eyebrow">VERIFY ONCE. SHARE WITH PERMISSION.</div><h2 style="margin:8px 0">A checkmark with a clear source</h2></div>${chip('Demo only','gray')}</div><p>The goal is a reusable result accepted by the state association. Evidence preparation, issuer verification and association acceptance are separate steps.</p><div class="recognition-grid"><div class="recognition-status"><div class="eyebrow">1 · Verification result</div><div style="margin:12px 0">${chip(c?labels[c.status]:'Not verified · sample only',valid?'':'gray')}</div><strong>${c?c.issuer:familyTools.verification}</strong><div class="sub">${c?'Reference: '+c.reference:'No issuer result yet'}</div></div><div class="recognition-status"><div class="eyebrow">2 · State association acceptance</div><div style="margin:12px 0">${chip('Pending agreement','amber')}</div><strong>${recognition.association} · proposed first partner</strong><div class="sub">No approval, partnership or acceptance agreement is in place.</div></div></div>${c?`<details style="margin-top:16px"><summary>View sample verification receipt</summary><dl class="receipt"><dt>Player</dt><dd>${c.subject}</dd><dt>Attribute</dt><dd>${c.attribute} verification only</dd><dt>Checked at</dt><dd>${c.checkedAt}</dd><dt>Rule reference</dt><dd>${c.rule} · illustrative</dd><dt>Validity</dt><dd>${c.validity}</dd><dt>Environment</dt><dd>Simulation · no real verification</dd></dl><p class="legal">No birth certificate, passport image or full birth date is included. Medical clearance and payment permissions remain separate.</p></details>`:''}<div class="note" style="margin-top:17px">${icon('shield')}<div><strong>${valid?'Verified in this simulation; association acceptance pending.':'No currently valid verification result in this simulation.'}</strong><br>This does not establish registration approval or eligibility to play. Until the association agrees to accept a reusable result, families must follow its existing registration and evidence-review process.</div></div>${controls?`<fieldset class="simulation-controls"><legend>Simulation controls · no external service connection</legend><p>Prepare sample age evidence above, then preview an issuer outcome. These controls never grant state-association acceptance.</p><div class="simulation-actions">${[['verified','Simulate verified'],['needs_review','Simulate needs review'],['expired','Simulate expired'],['revoked','Simulate revoked']].map(([value,label])=>`<button class="btn light" ${s.agePrepared?'':'disabled'} onclick="recordDemoVerification('${value}')">${label}</button>`).join('')}</div></fieldset>`:''}</section>`;
}
function onboardingValue(){return `<section class="card" style="margin-bottom:20px"><div class="eyebrow">CONNECTED PARENT + CLUB WALKTHROUGH</div><h2>Try the same application from both sides</h2><p>Configure a sample club template, review it as a parent and inspect the shared packet in a club queue. All responses are simulated.</p><a class="btn" style="display:inline-flex;align-items:center;min-height:48px;text-decoration:none" href="/locked-in/connected/index.html">Open connected onboarding lab →</a></section><section class="card" style="margin-bottom:20px"><div class="eyebrow">THE CLUB ONBOARDING JOURNEY</div><h2 style="margin:8px 0">One family profile. A template for every club.</h2><p>Parents reuse information they have already provided, review only what changed, and approve what this club needs. The club quickly checks the supplied age-verification and document references, then populates approved information into PlayMetrics, TeamSnap or its other software through its own backend integration.</p><div class="recognition-grid"><div class="recognition-status"><strong>For the family</strong><div class="sub">Reusable player information · Clear requirements · Selected sharing · Fewer repeat forms</div></div><div class="recognition-status"><strong>For the club</strong><div class="sub">Standard fields · Missing-item tracking · Fewer manual follow-ups · Agreed backend connection</div></div></div><details style="margin-top:15px"><summary>Illustrative club time savings</summary><p>Assume five fewer staff minutes per registration: 10,000 registrations would release about 833 staff hours; 20,000 would release about 1,667. At an assumed $30 per staff hour, that is approximately $25,000–$50,000 in staff capacity per onboarding cycle, before implementation, licensing and support costs.</p><p class="legal">Scenario only, not measured savings or a pricing promise. A pilot must measure review time, follow-up work, completion rate and integration costs. Released capacity becomes cash savings only where spending is actually reduced.</p></details><p class="legal" style="margin-bottom:0">Proposed journey only. No live single sign-on or backend integration is connected. Reuse of association-verified status remains subject to state acceptance. School compliance is a separate future scope.</p></section>`}
const registrationBeforeRecognition=views.registration;
views.registration=s=>onboardingValue()+registrationBeforeRecognition(s).replace('<div class="sectiontitle"><h2>Review & submit</h2>',recognitionPanel(s,true)+'<div class="sectiontitle"><h2>Review & submit</h2>').replace('All three items are required for this POC.','A current simulated age-verification result, clearance and test payment method are required.');
for(const viewName of ['playerprofile','verification','integrations']){const originalView=views[viewName];views[viewName]=s=>originalView(s)+recognitionPanel(s);}
const workflowBeforeRecognition=views.workflow;
views.workflow=s=>workflowBeforeRecognition(s)+`<div class="sectiontitle"><h2>The state-association acceptance gate</h2></div><div class="card"><ol class="bullets"><li>Agree who may issue the verification and which evidence and rules are accepted.</li><li>Connect an authorized status feed with an agreed player mapping.</li><li>Record the association, accepted attribute, policy version, reference and validity.</li><li>Share a current result only for the parent-approved recipient and purpose.</li><li>Withdraw or expire access and refresh stale or revoked results.</li></ol><p>Acceptance is specific to the association, competition and verified attribute. An age check does not confirm medical clearance, payment or full registration eligibility.</p><p class="legal">School athletics and school compliance remain a separate future scope. This demo does not implement those rules.</p></div>`;
const originalOpenPanel=openPanel;
openPanel=function(type){originalOpenPanel(type);if(type==='proof'){document.querySelector('.panel').insertAdjacentHTML('beforeend',recognitionPanel(state()));}};

document.addEventListener('keydown',e=>{if(e.key==='Escape')closePanel()});document.getElementById('toplock').innerHTML=icon('lock');document.getElementById('sidelock').innerHTML=icon('shield');document.getElementById('walkbutton').innerHTML=icon('flow')+' Walk through the flow';render();

